/**
 * Resolves this org's Release Relay connections and lets an admin save them.
 *
 * A connection is one RLY_Repo_Connection__c record. Its Type says how releases move:
 *   GitHub, GitLab, Bitbucket, AzureDevOps   pull request + pipeline in that Git provider
 *   DevOpsCenter                             releases run in Salesforce DevOps Center (link and guide)
 *
 * An org can have several connections. A record applies to this org when its Org Id matches;
 * else when its Sandbox Name matches (PRODUCTION for production and Developer Edition);
 * else records keyed Default... or with neither value are used.
 *
 * Earlier versions kept connections in RLY_Connection__mdt. Those are still read while this org
 * has no RLY_Repo_Connection__c records, and migrate() copies them across once.
 */
public with sharing class RlySettings {

    /** Stored in Metadata Types when every detectable type is picked. */
    @TestVisible private static final String ALL_TYPES = '*';

    /** The Metadata Types value to store: '*' for every detectable type, else the comma list. */
    @TestVisible
    private static String storedTypes(List<String> types) {
        if (types == null || types.isEmpty()) {
            return null;
        }
        Set<String> picked = new Set<String>();
        for (String t : types) {
            picked.add(t.trim());
        }
        if (picked.containsAll(RlyChangeService.detectableTypes())) {
            return ALL_TYPES;
        }
        return String.join(types, ',');
    }


    public class SettingsException extends Exception {}

    public static final String GITHUB = 'GitHub';
    public static final String GITLAB = 'GitLab';
    public static final String BITBUCKET = 'Bitbucket';
    public static final String AZURE = 'AzureDevOps';
    public static final String DEVOPS_CENTER = 'DevOpsCenter';
    public static final Set<String> GIT_TYPES = new Set<String>{ GITHUB, GITLAB, BITBUCKET, AZURE };
    private static final Map<String, String> DEFAULT_CREDENTIAL = new Map<String, String>{
        GITHUB => 'RLY_GitHub', GITLAB => 'RLY_GitLab', BITBUCKET => 'RLY_Bitbucket', AZURE => 'RLY_AzureDevOps'
    };
    private static final Map<String, String> DEFAULT_PIPELINE = new Map<String, String>{
        GITHUB => 'release-relay.yml', GITLAB => '.gitlab-ci.yml', BITBUCKET => 'release-relay', AZURE => ''
    };

    public static final String ADMIN_PERMISSION = 'RLY_Admin';
    public static final String APPROVER_PERMISSION = 'RLY_Approver';
    public static final Pattern BRANCH = Pattern.compile('^(feature|bugfix|hotfix)/[a-z0-9._-]{1,100}$');
    private static final Pattern REF = Pattern.compile('^[A-Za-z0-9._/-]{1,100}$');
    private static final Pattern ENV_NAME = Pattern.compile('^[A-Za-z0-9 _.-]{1,80}$');
    private static final Pattern PIPELINE = Pattern.compile('^[A-Za-z0-9_./-]{1,120}$');
    private static final Pattern PATH = Pattern.compile('^[A-Za-z0-9_./-]{1,200}$');
    private static final Pattern TYPE_NAME = Pattern.compile('^[A-Za-z]{2,80}$');
    private static final Pattern API_NAME = Pattern.compile('^[A-Za-z][A-Za-z0-9_]{0,79}$');
    private static final Pattern HTTPS_URL = Pattern.compile('^https://\\S{4,250}$');

    @TestVisible private static List<RLY_Repo_Connection__c> testRecords;
    @TestVisible private static List<RLY_Connection__mdt> testLegacyRecords;
    @TestVisible private static String testSandboxName;

    /** Editable connection values, as the page sends and shows them. */
    public class Connection {
        @AuraEnabled public String settingName;
        @AuraEnabled public String label;
        @AuraEnabled public String connectionType;
        @AuraEnabled public String namedCredential;
        @AuraEnabled public Boolean matchesThisOrg;
        @AuraEnabled public String sandboxName;
        @AuraEnabled public String orgLabel;
        // Git
        @AuraEnabled public String repository;
        @AuraEnabled public String environment;
        @AuraEnabled public List<String> targets;
        @AuraEnabled public String deployEnvironments; // target=environment, comma separated
        @AuraEnabled public String workflowFile;       // GitHub workflow file, GitLab CI file, Bitbucket custom pipeline, Azure pipeline id
        @AuraEnabled public String workflowRef;
        @AuraEnabled public String sourcePath;
        // DevOps Center
        @AuraEnabled public String devopsUrl;
        @AuraEnabled public String devopsProject;
        @AuraEnabled public String devopsPipeline;
        // All
        @AuraEnabled public Boolean allowSelfApproval;
        @AuraEnabled public Boolean codeScan;
        @AuraEnabled public Boolean isLegacy;          // still read from the old custom metadata
        @AuraEnabled public List<String> metadataTypes;
        @AuraEnabled public Integer lookbackDays;      // null: any time
        @AuraEnabled public Boolean isAdmin;
        @AuraEnabled public Boolean isApprover;
        @AuraEnabled public Integer daysSinceRefresh; // null in production
        @AuraEnabled public Boolean isGit;
        @AuraEnabled public Boolean isDevOpsCenter;
        @AuraEnabled public String changeLabel;       // pull request or merge request

        /** Environment of the org behind a target branch, or '' when that target isn't deployed. */
        public String deployEnvironmentFor(String target) {
            for (String pair : splitList(deployEnvironments)) {
                List<String> parts = pair.split('=');
                if (parts.size() == 2 && parts[0].trim() == target) {
                    return parts[1].trim();
                }
            }
            return '';
        }
    }

    /** Every connection record that applies to this org. */
    public static List<RLY_Repo_Connection__c> records() {
        List<RLY_Repo_Connection__c> all = allRecords();
        String orgId = String.valueOf(UserInfo.getOrganizationId()).left(15);
        String sandbox = currentSandboxName();
        List<RLY_Repo_Connection__c> byOrg = new List<RLY_Repo_Connection__c>();
        List<RLY_Repo_Connection__c> bySandbox = new List<RLY_Repo_Connection__c>();
        List<RLY_Repo_Connection__c> fallback = new List<RLY_Repo_Connection__c>();
        for (RLY_Repo_Connection__c s : all) {
            if (s.Type__c == 'OrgToOrg') {
                continue; // org to org connections are no longer supported
            }
            if (String.isNotBlank(s.Org_Id__c)) {
                if (s.Org_Id__c.trim().left(15) == orgId) {
                    byOrg.add(s);
                }
            } else if (String.isNotBlank(s.Sandbox_Name__c) && s.Sandbox_Name__c.trim().equalsIgnoreCase(sandbox)) {
                bySandbox.add(s);
            } else if (String.isBlank(s.Sandbox_Name__c) || String.valueOf(s.Key__c).startsWith('Default')) {
                fallback.add(s);
            }
        }
        List<RLY_Repo_Connection__c> out = !byOrg.isEmpty() ? byOrg : !bySandbox.isEmpty() ? bySandbox : fallback;
        if (out.isEmpty()) {
            throw new SettingsException('No Release Relay connection for this org. An admin can add one on the Connections page.');
        }
        return out;
    }

    /** Connection records, or the old custom metadata ones (unsaved copies) while there are none. */
    private static List<RLY_Repo_Connection__c> allRecords() {
        if (testRecords != null) {
            return testRecords;
        }
        List<RLY_Repo_Connection__c> rows = new Data().connections();
        if (!rows.isEmpty()) {
            return rows;
        }
        return legacyRecords();
    }

    /** The old RLY_Connection__mdt records as unsaved RLY_Repo_Connection__c rows. */
    @TestVisible
    private static List<RLY_Repo_Connection__c> legacyRecords() {
        List<RLY_Connection__mdt> old = testLegacyRecords != null ? testLegacyRecords : RLY_Connection__mdt.getAll().values();
        List<RLY_Repo_Connection__c> out = new List<RLY_Repo_Connection__c>();
        for (RLY_Connection__mdt m : old) {
            out.add(new RLY_Repo_Connection__c(
                Name = String.isBlank(m.MasterLabel) ? m.DeveloperName : m.MasterLabel,
                Key__c = m.DeveloperName, Type__c = m.Type__c, Org_Id__c = m.Org_Id__c, Sandbox_Name__c = m.Sandbox_Name__c,
                Org_Label__c = m.Org_Label__c, Named_Credential__c = m.Named_Credential__c, Repository__c = m.Repository__c,
                GitHub_Environment__c = m.GitHub_Environment__c, Target_Branches__c = m.Target_Branches__c,
                Deploy_Environments__c = m.Deploy_Environments__c, Workflow_File__c = m.Workflow_File__c,
                Workflow_Ref__c = m.Workflow_Ref__c, Source_Path__c = m.Source_Path__c,
                DevOps_Center_Url__c = m.DevOps_Center_Url__c, DevOps_Project__c = m.DevOps_Project__c,
                DevOps_Pipeline__c = m.DevOps_Pipeline__c, Allow_Self_Approval__c = m.Allow_Self_Approval__c == true,
                Code_Scan__c = true,
                Metadata_Types__c = m.Metadata_Types__c, Lookback_Days__c = null));
        }
        return out;
    }

    /**
     * Copies the old custom metadata connections into RLY_Repo_Connection__c, once. Keys stay the same,
     * so existing releases keep pointing at their connection. Returns how many were copied.
     */
    public static Integer migrate() {
        if (testRecords == null && !new Data().connections().isEmpty()) {
            return 0;
        }
        List<RLY_Repo_Connection__c> rows = new List<RLY_Repo_Connection__c>();
        for (RLY_Repo_Connection__c c : legacyRecords()) {
            if (c.Type__c != 'OrgToOrg') {
                rows.add(c);
            }
        }
        new Data().upsertAll(rows);
        return rows.size();
    }

    /** The first connection record for this org. */
    public static RLY_Repo_Connection__c current() {
        return records()[0];
    }

    public static List<Connection> connections() {
        List<Connection> out = new List<Connection>();
        for (RLY_Repo_Connection__c s : records()) {
            out.add(toConnection(s));
        }
        return out;
    }

    /** The connection with this key; when blank, the first one. */
    public static Connection connection(String settingName) {
        List<RLY_Repo_Connection__c> recs = records();
        if (String.isBlank(settingName)) {
            return toConnection(recs[0]);
        }
        for (RLY_Repo_Connection__c s : recs) {
            if (s.Key__c == settingName) {
                return toConnection(s);
            }
        }
        throw new SettingsException('Connection ' + settingName + ' isn\'t set up for this org.');
    }

    public static Connection currentConnection() {
        return connection(null);
    }

    /** Upper-case sandbox name from My Domain, or PRODUCTION. */
    public static String currentSandboxName() {
        if (testSandboxName != null) {
            return testSandboxName;
        }
        try {
            String name = System.DomainParser.parse(URL.getOrgDomainUrl()).getSandboxName();
            return String.isBlank(name) ? 'PRODUCTION' : name.toUpperCase();
        } catch (Exception e) {
            return 'UNKNOWN';
        }
    }

    public static Connection toConnection(RLY_Repo_Connection__c s) {
        Connection c = new Connection();
        c.settingName = s.Key__c;
        c.label = String.isBlank(s.Name) ? s.Key__c : s.Name;
        c.connectionType = String.isBlank(s.Type__c) ? GITHUB : s.Type__c;
        c.namedCredential = String.isNotBlank(s.Named_Credential__c) ? s.Named_Credential__c.trim() : DEFAULT_CREDENTIAL.get(c.connectionType);
        c.sandboxName = currentSandboxName();
        c.matchesThisOrg = String.isNotBlank(s.Org_Id__c)
            ? s.Org_Id__c.trim().left(15) == String.valueOf(UserInfo.getOrganizationId()).left(15)
            : String.isNotBlank(s.Sandbox_Name__c) && s.Sandbox_Name__c.trim().equalsIgnoreCase(c.sandboxName);
        c.orgLabel = String.isBlank(s.Org_Label__c) ? c.sandboxName : s.Org_Label__c;
        c.repository = s.Repository__c;
        c.environment = s.GitHub_Environment__c;
        c.targets = splitList(s.Target_Branches__c);
        c.deployEnvironments = s.Deploy_Environments__c;
        c.workflowFile = String.isNotBlank(s.Workflow_File__c) ? s.Workflow_File__c : DEFAULT_PIPELINE.get(c.connectionType);
        c.workflowRef = String.isBlank(s.Workflow_Ref__c) ? 'main' : s.Workflow_Ref__c;
        c.sourcePath = String.isBlank(s.Source_Path__c) ? 'force-app/main/default' : s.Source_Path__c.removeEnd('/');
        c.devopsUrl = s.DevOps_Center_Url__c;
        c.devopsProject = s.DevOps_Project__c;
        c.devopsPipeline = s.DevOps_Pipeline__c;
        c.allowSelfApproval = s.Allow_Self_Approval__c == true;
        c.codeScan = s.Code_Scan__c != false;
        c.isLegacy = s.Id == null && testRecords == null;
        // '*' means every detectable type (older connections stored it to fit 255 characters).
        c.metadataTypes = String.isBlank(s.Metadata_Types__c) || s.Metadata_Types__c == ALL_TYPES
            ? RlyChangeService.detectableTypes() : splitList(s.Metadata_Types__c);
        c.lookbackDays = s.Lookback_Days__c == null || s.Lookback_Days__c <= 0 ? null : s.Lookback_Days__c.intValue();
        c.isAdmin = isAdmin();
        c.isApprover = isApprover();
        c.daysSinceRefresh = daysSinceRefresh();
        c.isGit = GIT_TYPES.contains(c.connectionType);
        c.isDevOpsCenter = c.connectionType == DEVOPS_CENTER;
        c.changeLabel = c.connectionType == GITLAB ? 'merge request' : 'pull request';
        return c;
    }

    /** Days since this sandbox was created or last refreshed; null in production. */
    @TestVisible
    private static Integer daysSinceRefresh() {
        List<Organization> orgs = [SELECT IsSandbox, CreatedDate FROM Organization LIMIT 1];
        if (orgs.isEmpty() || orgs[0].IsSandbox != true) {
            return null;
        }
        return orgs[0].CreatedDate.date().daysBetween(Date.today());
    }

    public static Boolean isAdmin() {
        return FeatureManagement.checkPermission(ADMIN_PERMISSION);
    }

    public static Boolean isApprover() {
        return FeatureManagement.checkPermission(APPROVER_PERMISSION) || isAdmin();
    }

    /** Throws unless the target is one of this connection's targets. */
    public static void assertTarget(Connection c, String target) {
        if (String.isBlank(target) || !c.targets.contains(target)) {
            throw new SettingsException('This connection can only release into: ' + String.join(c.targets, ', ') + '.');
        }
    }

    /**
     * Saves a connection for this org (admins only): updates the record with this key when it
     * belongs to this org, otherwise creates one tied to this org's Id. Saved at once.
     */
    public static String save(Connection input) {
        if (!isAdmin()) {
            throw new SettingsException('Only users with the Release Relay Admin permission set can change connections.');
        }
        validate(input);
        Data data = new Data();
        RLY_Repo_Connection__c existing;
        if (String.isNotBlank(input.settingName)) {
            existing = data.byKey(input.settingName);
            if (existing != null && !toConnection(existing).matchesThisOrg) {
                existing = null;
            }
        }
        String label = String.isBlank(input.label) ? input.orgLabel + ' ' + input.connectionType : input.label.trim();
        String key = existing != null ? existing.Key__c
            // An old custom metadata connection keeps its name, so its releases still find it.
            : String.isNotBlank(input.settingName) && input.isLegacy == true && data.byKey(input.settingName) == null ? input.settingName
            : ('C_' + label + '_' + String.valueOf(UserInfo.getOrganizationId()).right(6))
                .replaceAll('[^A-Za-z0-9]+', '_').removeEnd('_').left(40).removeEnd('_');
        RLY_Repo_Connection__c row = new RLY_Repo_Connection__c(Key__c = key);
        row.Name = label.left(80);
        row.Type__c = input.connectionType;
        row.Org_Id__c = String.valueOf(UserInfo.getOrganizationId());
        row.Sandbox_Name__c = currentSandboxName();
        row.Org_Label__c = input.orgLabel.trim();
        row.Named_Credential__c = blankToNull(input.namedCredential);
        row.Repository__c = blankToNull(input.repository);
        row.GitHub_Environment__c = blankToNull(input.environment);
        row.Target_Branches__c = String.join(input.targets, ',');
        row.Deploy_Environments__c = String.isBlank(input.deployEnvironments) ? null : input.deployEnvironments.replaceAll('\\s', '');
        row.Workflow_File__c = blankToNull(input.workflowFile);
        row.Workflow_Ref__c = blankToNull(input.workflowRef);
        row.Source_Path__c = String.isBlank(input.sourcePath) ? null : input.sourcePath.trim().removeEnd('/');
        row.DevOps_Center_Url__c = blankToNull(input.devopsUrl);
        row.DevOps_Project__c = blankToNull(input.devopsProject);
        row.DevOps_Pipeline__c = blankToNull(input.devopsPipeline);
        row.Metadata_Types__c = storedTypes(input.metadataTypes);
        row.Allow_Self_Approval__c = input.allowSelfApproval == true;
        row.Code_Scan__c = input.codeScan != false;
        row.Lookback_Days__c = input.lookbackDays == null || input.lookbackDays <= 0 ? null : input.lookbackDays;
        data.upsertAll(new List<RLY_Repo_Connection__c>{ row });
        return key;
    }

    @TestVisible
    private static void validate(Connection c) {
        List<String> problems = new List<String>();
        if (c.connectionType == null || !(GIT_TYPES.contains(c.connectionType) || c.connectionType == DEVOPS_CENTER)) {
            throw new SettingsException('Pick a connection type.');
        }
        if (String.isNotBlank(c.label) && c.label.trim().length() > 40) { problems.add('Connection name can be up to 40 characters'); }
        if (String.isBlank(c.orgLabel) || c.orgLabel.length() > 40) { problems.add('Org label is required, up to 40 characters'); }
        if (String.isNotBlank(c.namedCredential) && !API_NAME.matcher(c.namedCredential.trim()).matches()) { problems.add('Named Credential must be an API name'); }
        if (c.targets == null || c.targets.isEmpty()) { problems.add('Add at least one target'); }
        else {
            for (String t : c.targets) {
                if (!REF.matcher(t).matches()) { problems.add('Target "' + t + '" has characters that aren\'t allowed'); }
            }
            if (String.join(c.targets, ',').length() > 255) { problems.add('Targets must fit in 255 characters'); }
        }
        if (c.connectionType != DEVOPS_CENTER) {
            if (c.metadataTypes == null || c.metadataTypes.isEmpty()) { problems.add('Pick at least one metadata type'); }
            else {
                for (String t : c.metadataTypes) {
                    if (!TYPE_NAME.matcher(t).matches()) { problems.add('"' + t + '" isn\'t a metadata type name'); }
                }
            }
            if (c.lookbackDays != null && (c.lookbackDays < 0 || c.lookbackDays > 365)) { problems.add('Days back must be blank (any time) or 1 to 365'); }
        }
        if (GIT_TYPES.contains(c.connectionType)) {
            validateGit(c, problems);
        } else {
            if (String.isBlank(c.devopsUrl) || !HTTPS_URL.matcher(c.devopsUrl.trim()).matches()) { problems.add('DevOps Center link must be an https address'); }
        }
        if (!problems.isEmpty()) {
            throw new SettingsException(String.join(problems, '. ') + '.');
        }
    }

    private static void validateGit(Connection c, List<String> problems) {
        if (String.isBlank(c.environment) || !ENV_NAME.matcher(c.environment.trim()).matches()) { problems.add('Environment is required'); }
        if (String.isBlank(c.workflowRef) || !REF.matcher(c.workflowRef.trim()).matches()) { problems.add('Pipeline branch is required'); }
        if (String.isNotBlank(c.workflowFile) && !PIPELINE.matcher(c.workflowFile.trim()).matches()) { problems.add('Pipeline has characters that aren\'t allowed'); }
        if (String.isBlank(c.sourcePath) || !PATH.matcher(c.sourcePath.trim()).matches() || c.sourcePath.contains('..')) { problems.add('Source path must be a folder such as force-app/main/default'); }
        if (String.isNotBlank(c.deployEnvironments)) {
            for (String pair : splitList(c.deployEnvironments.replaceAll('\\s', ''))) {
                List<String> parts = pair.split('=');
                if (parts.size() != 2 || c.targets == null || !c.targets.contains(parts[0]) || !ENV_NAME.matcher(parts[1]).matches()) {
                    problems.add('Deploy environments must be target=environment pairs for this connection\'s targets, for example sit=sit');
                    break;
                }
            }
            if (c.deployEnvironments.length() > 255) { problems.add('Deploy environments must fit in 255 characters'); }
        }
        try {
            Connection probe = (Connection) JSON.deserialize(JSON.serialize(c), Connection.class);
            probe.namedCredential = String.isBlank(c.namedCredential) ? DEFAULT_CREDENTIAL.get(c.connectionType) : c.namedCredential;
            probe.workflowFile = String.isBlank(c.workflowFile) ? DEFAULT_PIPELINE.get(c.connectionType) : c.workflowFile;
            probe.label = String.isBlank(c.label) ? c.connectionType : c.label;
            RlyGitProvider.forConnection(probe);
        } catch (RlyGitProvider.GitException e) {
            problems.add(e.getMessage().removeEnd('.'));
        }
    }

    public static List<String> splitList(String value) {
        List<String> out = new List<String>();
        if (String.isBlank(value)) {
            return out;
        }
        for (String part : value.split(',')) {
            if (String.isNotBlank(part)) {
                out.add(part.trim());
            }
        }
        return out;
    }

    private static String blankToNull(String value) {
        return String.isBlank(value) ? null : value.trim();
    }

    /** Connections are read by everyone with the tab and written only after the admin check above. */
    private without sharing class Data {
        public List<RLY_Repo_Connection__c> connections() {
            return [SELECT Id, Name, Key__c, Type__c, Org_Id__c, Sandbox_Name__c, Org_Label__c, Named_Credential__c,
                           Repository__c, GitHub_Environment__c, Target_Branches__c, Deploy_Environments__c,
                           Workflow_File__c, Workflow_Ref__c, Source_Path__c, DevOps_Center_Url__c, DevOps_Project__c,
                           DevOps_Pipeline__c, Allow_Self_Approval__c, Code_Scan__c, Metadata_Types__c, Lookback_Days__c
                    FROM RLY_Repo_Connection__c ORDER BY CreatedDate ASC LIMIT 200];
        }
        public RLY_Repo_Connection__c byKey(String key) {
            if (testRecords != null) {
                for (RLY_Repo_Connection__c c : testRecords) {
                    if (c.Key__c == key) {
                        return c;
                    }
                }
                return null;
            }
            List<RLY_Repo_Connection__c> rows = [SELECT Id, Key__c, Org_Id__c, Sandbox_Name__c, Name FROM RLY_Repo_Connection__c WHERE Key__c = :key LIMIT 1];
            return rows.isEmpty() ? null : rows[0];
        }
        public void upsertAll(List<RLY_Repo_Connection__c> rows) {
            if (!rows.isEmpty()) {
                upsert rows Key__c;
            }
        }
    }
}
